draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(th - 0.4), y1 - 8 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(th + 0.4), y1 - 8 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

var panel = W / 3;
var cy = H * 0.45;
var L = Math.min(panel * 0.26, H * 0.24);
var k;
for (k = 1; k < 3; k++) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(panel * k, H * 0.06); ctx.lineTo(panel * k, H * 0.94); ctx.stroke();
}

// panel 1: top of a vertical circle
var c1 = panel * 0.5;
ctx.fillStyle = C.ink;
ctx.fillText("1. Top of the loop", c1 - panel * 0.4, H * 0.14);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c1, cy, 7, 0, Math.PI * 2); ctx.fill();
arrow(c1, cy, c1, cy + L, C.figure);
arrow(c1 - 14, cy, c1 - 14, cy + L * 0.7, C.accent);
ctx.fillStyle = C.figure; ctx.fillText("mg", c1 + 6, cy + L * 0.55);
ctx.fillStyle = C.accent; ctx.fillText("T", c1 - 30, cy + L * 0.45);
ctx.fillStyle = C.ink;
ctx.fillText("centre is BELOW", c1 - panel * 0.36, cy + L + 26);
ctx.fillText("T + mg = m v^2 / r", c1 - panel * 0.36, cy + L + 42);

// panel 2: bottom of a vertical circle
var c2 = panel * 1.5;
ctx.fillStyle = C.ink;
ctx.fillText("2. Bottom of the loop", c2 - panel * 0.42, H * 0.14);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c2, cy, 7, 0, Math.PI * 2); ctx.fill();
arrow(c2, cy, c2, cy + L, C.figure);
arrow(c2 - 14, cy, c2 - 14, cy - L, C.accent);
ctx.fillStyle = C.figure; ctx.fillText("mg", c2 + 6, cy + L * 0.6);
ctx.fillStyle = C.accent; ctx.fillText("T", c2 - 30, cy - L * 0.6);
ctx.fillStyle = C.ink;
ctx.fillText("centre is ABOVE", c2 - panel * 0.36, cy + L + 26);
ctx.fillText("T - mg = m v^2 / r", c2 - panel * 0.36, cy + L + 42);

// panel 3: flat curve, seen from behind
var c3 = panel * 2.5;
ctx.fillStyle = C.ink;
ctx.fillText("3. Flat curve, from behind", c3 - panel * 0.46, H * 0.14);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(c3 - panel * 0.4, cy + L * 0.6); ctx.lineTo(c3 + panel * 0.4, cy + L * 0.6); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillRect(c3 - 14, cy + L * 0.6 - 16, 28, 16);
arrow(c3, cy + L * 0.6 - 8, c3, cy + L * 0.6 - 8 + L * 0.75, C.figure);
arrow(c3 + 18, cy + L * 0.6 - 8, c3 + 18, cy + L * 0.6 - 8 - L * 0.75, C.figure);
arrow(c3, cy + L * 0.6 - 8, c3 - L * 0.8, cy + L * 0.6 - 8, C.accent);
ctx.fillStyle = C.figure;
ctx.fillText("mg", c3 + 4, cy + L * 0.6 - 8 + L * 0.6);
ctx.fillText("N", c3 + 22, cy + L * 0.6 - 8 - L * 0.6);
ctx.fillStyle = C.accent;
ctx.fillText("f_s (inward)", c3 - L * 0.8 - 6, cy + L * 0.6 - 18);
ctx.fillStyle = C.ink;
ctx.fillText("f_s = m v^2 / r", c3 - panel * 0.36, cy + L + 26);
ctx.fillText("f_s <= mu_s m g", c3 - panel * 0.36, cy + L + 42);

ctx.fillStyle = C.faint;
ctx.fillText("No arrow is ever labelled 'centripetal force'. The label names the source; m v^2 / r is the answer it must add up to.", W * 0.03, H * 0.96);
